@Composable
fun EditMedicationDialog(
    medication: Medication,
    onDismiss: () -> Unit,
    onSave: (Medication) -> Unit,
    onDelete: (Medication) -> Unit,
) {
    var name by remember { mutableStateOf(medication.name) }
    var defaultDose by remember { mutableStateOf(medication.defaultDose) }
    var intervalHours by remember { mutableStateOf((medication.minIntervalMinutes ?: 0) / 60) }
    var intervalMinutes by remember { mutableStateOf((medication.minIntervalMinutes ?: 0) % 60) }

    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text(stringResource(R.string.edit_medication_title)) },
        text = {
            Column {
                OutlinedTextField(
                    value = name,
                    onValueChange = { name = it },
                    label = { Text(stringResource(R.string.name_label)) },
                    modifier = Modifier.fillMaxWidth(),
                )
                OutlinedTextField(
                    value = defaultDose,
                    onValueChange = { defaultDose = it },
                    label = { Text(stringResource(R.string.default_dose_label)) },
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(top = 8.dp),
                )
                Text(
                    stringResource(R.string.min_interval_label),
                    style = MaterialTheme.typography.labelLarge,
                    modifier = Modifier.padding(top = 16.dp),
                )
                DurationPicker(
                    hours = intervalHours,
                    minutes = intervalMinutes,
                    onHoursChange = { intervalHours = it },
                    onMinutesChange = { intervalMinutes = it },
                    modifier = Modifier.padding(top = 4.dp),
                )
            }
        },
        confirmButton = {
            Row {
                TextButton(
                    onClick = { onDelete(medication) },
                    colors = ButtonDefaults.textButtonColors(
                        contentColor = MaterialTheme.colorScheme.error,
                    ),
                ) {
                    Text(stringResource(R.string.delete))
                }
                TextButton(
                    onClick = {
                        if (name.isNotBlank() && defaultDose.isNotBlank()) {
                            val minIntervalMinutes = (intervalHours * 60 + intervalMinutes).takeIf { it > 0 }
                            onSave(
                                medication.copy(
                                    name = name,
                                    defaultDose = defaultDose,
                                    minIntervalMinutes = minIntervalMinutes,
                                ),
                            )
                        }
                    },
                ) {
                    Text(stringResource(R.string.save))
                }
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) { Text(stringResource(R.string.cancel)) }
        },
    )
}
